npm init -y > /dev/null && npm i @cloud-copilot/iam-simulate@0.1.173 && cat > can.mjs <<'EOF'
import { readFileSync } from "node:fs";
import { runSimulation } from "@cloud-copilot/iam-simulate";

const [file, action, resource, ...context] = process.argv.slice(2);
const policy = JSON.parse(readFileSync(file, "utf8"));

const answer = await runSimulation({
  identityPolicies: [{ name: file, policy }],
  serviceControlPolicies: [],
  resourceControlPolicies: [],
  request: {
    principal: "arn:aws:iam::000000000000:role/lab",
    action,
    resource: { resource, accountId: "000000000000" },
    contextVariables: Object.fromEntries(context.map((pair) => pair.split("="))),
  },
}, {});

console.log(action.padEnd(38), answer.overallResult ?? answer.errors);
EOF

